#include "vtf_block_decode.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("input and output prefix required");std::ifstream f(argv[1],std::ios::binary);if(!f)throw std::runtime_error("input read");const std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});const auto l=readVtfTextureLayoutCandidate(b);unsigned decoded=0;for(const auto&m:l.mips)for(uint32_t frame=0;frame<l.frameCount;++frame){const auto image=decodeVtfMipCandidate(b,m.level,frame);const std::string path=std::string(argv[2])+"-m"+std::to_string(m.level)+"-f"+std::to_string(frame)+".rgba";std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(image.rgba.data()),std::streamsize(image.rgba.size()));out.close();if(!out)throw std::runtime_error("output write");++decoded;}std::cout<<"frames="<<l.frameCount<<" mips="<<l.mips.size()<<" decoded="<<decoded<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
